 9	method mcontained(v:array<int>,w:array<int>,n:int,m:int) returns (b:bool)
10	//Specify and implement an O(m+n) algorithm that returns b
11	//v and w are strictly increasing ordered arrays
12	//b is true iff the first n elements of v are contained in the first m elements of w
13	requires n<= (m) + 1 && n>=0
14	requires strictSorted(v[..])
15	requires strictSorted(w[..])
16	requires v.Length >= n && w.Length >= m
17	ensures b==forall k:: 0<= k< n ==> v[k] in w[..m]//exists j :: 0 <= j < m && v[k] == w[j]
18	{
19		var i:=0;
20		var j:=0;
21		while(i<n && j<m && (v[i] >= w[j])) //&& b)
22		invariant 0<=i<=n
23		invariant 0<=j<=m
24		invariant strictSorted(v[..])
25		invariant strictSorted(w[..])
26		invariant forall k::0<=k<i ==> v[k] in w[..j] 
27		invariant i<n  ==> !(v[i] in w[..j])
28		decreases w.Length-j
29		decreases v.Length-i
30		{	
31			if(v[i] == w[j]){
32				i:=i+1;
33			}
34			j:=j+1;
35			
36		}
37		assert i<n ==> !(v[i] in w[..m]);
38		b := i==n;
39		
40	}
